// Set by main.ts from the Studio's language (the one chosen in Blup).
const byLang: Record<string, typeof pt> = { pt, en, es };
export let t = byLang[navigator.language.toLowerCase().slice(0, 2)] ?? en;
export function setLanguage(lang: string) {
  t = byLang[lang] ?? en;
  document.documentElement.lang = lang;
}
